// Menus 규칙 — M3 Menus Accessibility(키보드) · Guidelines(배치 · 선택), Compose DropdownMenuPositionProvider(여백 · 뒤집기).
// 순수 계산만 두고(단위 테스트 대상) DOM 조작은 patterns.js가 한다.

/** 메뉴 항목 이동 — 위 · 아래 화살표(끝에서 감쌈), Home · End. 비활성 항목도 포커스를 받는다(M3 Interactability). */
function menuNextIndex(index, count, key) {
  if (count <= 0) return -1;
  if (key === 'Home') return 0;
  if (key === 'End') return count - 1;
  if (key === 'ArrowDown') return (index + 1) % count;
  if (key === 'ArrowUp') return (index - 1 + count) % count;
  return index;
}

/** 글자로 이동 — 현재 다음 항목부터 그 글자로 시작하는 첫 항목(감쌈). 없으면 -1. */
function menuTypeahead(labels, index, char) {
  const c = String(char || '').toLocaleLowerCase();
  if (!c.trim()) return -1;
  for (let step = 1; step <= labels.length; step += 1) {
    const i = (index + step) % labels.length;
    if (String(labels[i]).trim().toLocaleLowerCase().startsWith(c)) return i;
  }
  return -1;
}

/** 선택 결과 — single은 고른 항목만, multi는 고른 항목만 뒤집는다. */
function menuSelect(selected, index, mode) {
  if (mode === 'single') return selected.map((_, i) => i === index);
  return selected.map((on, i) => (i === index ? !on : on));
}

/** 선택 뒤 메뉴를 닫는가 — single은 닫고, multi는 사람이 닫을 때까지 열어 둔다(M3 Guidelines). */
function menuClosesOnSelect(mode) {
  return mode !== 'multi';
}

const MENU_MARGIN = { vertical: 48, horizontal: 8 };   // Compose MenuVerticalMargin · MenuHorizontalMargin

/**
 * 메뉴 위치 — 기준(버튼 · 포인터) 아래, 시작 쪽 정렬. 아래가 모자라고 위가 더 넓으면 위로, 끝이 넘치면 끝 정렬로 뒤집는다.
 * 하위 메뉴(kind 'side')는 부모 항목 옆(끝 쪽, 모자라면 시작 쪽), 윗변을 항목에 맞춘다.
 * 반환: { left, top, originX, originY } — origin은 열림 애니메이션(크기 0.8 → 1)의 기준점.
 */
function menuPlacement(anchor, menu, viewport, { kind = 'below', rtl = false, margin = MENU_MARGIN, gap = 0, align = 'start', prefer = 'below' } = {}) {
  const clamp = (v, lo, hi) => Math.min(Math.max(v, lo), Math.max(lo, hi));
  let left, top, originX, originY;
  if (kind === 'side') {
    const endRoom = rtl ? anchor.left - margin.horizontal : viewport.width - margin.horizontal - anchor.right;
    const toEnd = endRoom >= menu.width || endRoom >= (rtl ? viewport.width - anchor.right : anchor.left) - margin.horizontal;
    const goRight = rtl ? !toEnd : toEnd;
    left = goRight ? anchor.right : anchor.left - menu.width;
    originX = goRight ? 'left' : 'right';
    top = anchor.top;
    originY = 'top';
    if (top + menu.height > viewport.height - margin.horizontal) { top = anchor.bottom - menu.height; originY = 'bottom'; }
  } else {
    const below = viewport.height - margin.vertical - anchor.bottom - gap;
    const above = anchor.top - margin.vertical - gap;
    const down = prefer === 'above' ? !(above >= menu.height || above >= below) : below >= menu.height || below >= above;   // FAB 메뉴는 위 우선
    top = down ? anchor.bottom + gap : anchor.top - gap - menu.height;   // gap — FAB 메뉴(웹)는 FAB와 4 띄움(M3 FAB menu Specs)
    originY = down ? 'top' : 'bottom';
    const startAligned = rtl ? anchor.right - menu.width : anchor.left;
    const endAligned = rtl ? anchor.left : anchor.right - menu.width;
    const fits = x => x >= margin.horizontal && x + menu.width <= viewport.width - margin.horizontal;
    const [first, second] = align === 'end' ? [endAligned, startAligned] : [startAligned, endAligned];   // 끝 정렬 우선(FAB 메뉴)
    left = fits(first) ? first : fits(second) ? second : first;
    originX = (left === startAligned) !== rtl ? 'left' : 'right';
  }
  left = clamp(left, margin.horizontal, viewport.width - margin.horizontal - menu.width);
  top = clamp(top, margin.horizontal, viewport.height - margin.horizontal - menu.height);
  return { left, top, originX, originY };
}

// Search 규칙 — M3 Search(검색창 → 검색 뷰), WAI-ARIA combobox(입력 + 목록). 순수 계산만 둔다.

/** 제안 목록 거르기 — 빈 검색어면 처음 max개(최근 검색), 아니면 대소문자 무시 포함 검색. */
function searchFilter(items, query, max = 6) {
  const q = String(query || '').trim().toLocaleLowerCase();
  const list = q ? items.filter(item => String(item).toLocaleLowerCase().includes(q)) : items;
  return list.slice(0, max);
}

/**
 * 결과 목록 이동 — -1은 입력칸. 아래 화살표로 입력칸에서 첫 결과로, 위 화살표로 첫 결과에서 입력칸으로 돌아간다.
 * 끝에서는 멈춘다. Home · End는 입력칸 글자 이동이라 다루지 않는다.
 */
function searchNextIndex(index, count, key) {
  if (count <= 0) return -1;
  if (key === 'ArrowDown') return Math.min(count - 1, index + 1);
  if (key === 'ArrowUp') return Math.max(-1, index - 1);
  return index;
}

const SEARCH_BAR = { height: 56, minWidth: 360, maxWidth: 720 };   // MDC · Compose SearchBarTokens, Compose SearchBarMin/MaxWidth

// Tabs 규칙 — M3 Tabs(Primary · Secondary, Fixed · Scrollable), WAI-ARIA tabs(화살표로 포커스, Enter · Space로 선택).
// 순수 계산만 두고 DOM은 patterns.js가 다룬다.

const TABS = { minIndicator: 24, scrollEdge: 52, scrollMinTab: 90, padding: 16 };   // Compose PrimaryIndicator · ScrollableTabRow

/** 화살표 이동 — 끝에서 감싼다(WAI-ARIA), Home · End. RTL 가로는 좌우 반대. 비활성 칸은 건너뛴다. */
function tabsNextIndex(index, count, key, { rtl = false, disabled = [] } = {}) {
  if (count <= 0) return -1;
  const ok = i => !disabled.includes(i);
  const step = { ArrowRight: rtl ? -1 : 1, ArrowLeft: rtl ? 1 : -1 }[key];
  if (key === 'Home' || key === 'End') {
    const order = [...Array(count).keys()];
    if (key === 'End') order.reverse();
    return order.find(ok) ?? index;
  }
  if (!step) return index;
  for (let k = 1; k <= count; k += 1) {
    const i = (index + step * k + count * k) % count;
    if (ok(i)) return i;
  }
  return index;
}

/**
 * 표시기 위치 — primary는 내용(라벨 · 아이콘) 폭(최소 24)을 내용 가운데에, secondary는 칸 전체 폭.
 * tab = { left, width }, content = { left, width } (같은 기준 좌표)
 */
function tabsIndicator(variant, tab, content) {
  if (variant === 'secondary') return { left: tab.left, width: tab.width };
  const width = Math.max(TABS.minIndicator, content.width);
  return { left: content.left + content.width / 2 - width / 2, width };
}

/** 스크롤형에서 선택 칸이 보이도록 할 scrollLeft — 칸을 가운데로(경계 안으로 자름, Compose ScrollableTabRow). */
function tabsScrollTo(tab, viewport, scrollWidth) {
  const target = tab.left + tab.width / 2 - viewport / 2;
  return Math.max(0, Math.min(scrollWidth - viewport, Math.round(target)));
}

// Text fields 규칙 — M3 Text fields(Filled · Outlined). 순수 계산만 두고 DOM은 patterns.js가 다룬다.

/** M3 치수(Specs · Compose TextFieldImpl): 높이 56, 좌우 16(아이콘 있으면 12), 아이콘-글 16, 보조 글 위 4, 보조 글-글자 수 16 */
const TEXT_FIELD = { height: 56, padding: 16, iconPadding: 12, iconGap: 16, icon: 24, supportTop: 4, counterGap: 16, labelInset: 4, line: 24 };

/** 글자 수 — "사용 / 최대". 최대를 넘으면 over. 낭독용 문구는 "글자 수"(M3 Accessibility). */
function tfCounter(length, max) {
  const used = Math.max(0, length | 0);
  return { text: `${used}/${max}`, over: used > max, label: `글자 수 ${used}자, 최대 ${max}자` };
}

/** 보조 글 자리 — 오류가 있으면 보조 글을 오류 글로 바꾼다(덧붙이지 않음, M3 Error text). 오류는 role="alert". */
function tfMessage({ supporting = '', error = '' } = {}) {
  if (error) return { text: error, error: true, role: 'alert' };
  return { text: supporting, error: false, role: null };
}

/** 검증 — 필수 · 이메일 · 최대 길이. 오류 문구(없으면 ''). 오류 문구는 고치는 방법을 말한다(M3 Error text). */
function tfValidate(value, { required = false, type = 'text', maxLength = Infinity } = {}) {
  const v = String(value ?? '');
  if (required && !v.trim()) return '필수 항목입니다. 내용을 입력하세요.';
  if (v.length > maxLength) return `${maxLength}자 이하로 입력하세요.`;
  if (type === 'email' && v.trim() && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v.trim())) return '이메일 형식으로 입력하세요(예: name@example.com).';
  return '';
}

/** 여러 줄 필드 높이 — 내용 높이에 맞춰 늘어나고(최소 1줄), maxRows가 있으면 거기서 멈추고 스크롤. */
function tfAutoHeight(contentHeight, { line = TEXT_FIELD.line, minRows = 1, maxRows = Infinity } = {}) {
  const rows = Math.max(minRows, Math.ceil(Math.max(0, contentHeight) / line));
  const capped = Math.min(rows, maxRows);
  return { height: capped * line, scroll: rows > maxRows };
}

// Toolbars 규칙 — M3 Docked · Floating toolbar(Expressive). 순수 계산만 두고 DOM은 patterns.js가 다룬다.

/** 치수(MDC · Compose 토큰): 높이 · 폭 64, docked 좌우 16 · 항목 사이 4 ~ 32, floating 안 여백 8 · 사이 4 · 창 여백 16(세로 24), FAB와 8 */
const TOOLBAR = {
  height: 64, dockedPadding: 16, dockedMinGap: 4, dockedMaxGap: 32, floatingPadding: 8, floatingGap: 4,
  screenOffset: 16, verticalOffset: 24, fabGap: 8, fabMin: 56, fabMax: 80, scrollThreshold: 40,
};

/**
 * 스크롤 반응 — 한 방향으로 threshold 이상 움직이면 바뀐다(Compose FloatingToolbarDefaults.ScrollDistanceThreshold 40).
 * 아래로(내용이 올라감) → 숨김 · 접힘, 위로 → 보임 · 펼침. 맨 위면 늘 보임.
 * state = { shown, acc } → 새 state
 */
function toolbarScroll(state, dy, scrollTop, { threshold = TOOLBAR.scrollThreshold } = {}) {
  const shown = state?.shown ?? true;
  if (scrollTop <= 0) return { shown: true, acc: 0 };
  let acc = state?.acc ?? 0;
  acc = Math.sign(dy) === Math.sign(acc) || acc === 0 ? acc + dy : dy;   // 방향이 바뀌면 다시 센다
  if (acc >= threshold && shown) return { shown: false, acc: 0 };
  if (acc <= -threshold && !shown) return { shown: true, acc: 0 };
  return { shown, acc };
}

/** 접힘 진행도(0 펼침 · 1 접힘)에 따른 FAB 크기 — 56에서 80(Compose FabSizeRange) */
function toolbarFabSize(progress) {
  const p = Math.min(1, Math.max(0, progress));
  return Math.round(TOOLBAR.fabMin + (TOOLBAR.fabMax - TOOLBAR.fabMin) * p);
}

/** 화살표 이동(M3 Accessibility: Tab 또는 화살표). 가로는 ← →, 세로는 ↑ ↓, Home · End. 끝에서 멈춘다. */
function toolbarNextIndex(index, count, key, { vertical = false, rtl = false } = {}) {
  if (count <= 0) return -1;
  if (key === 'Home') return 0;
  if (key === 'End') return count - 1;
  const fwd = vertical ? 'ArrowDown' : (rtl ? 'ArrowLeft' : 'ArrowRight');
  const back = vertical ? 'ArrowUp' : (rtl ? 'ArrowRight' : 'ArrowLeft');
  if (key === fwd) return Math.min(count - 1, index + 1);
  if (key === back) return Math.max(0, index - 1);
  return index;
}

/** docked 고르게 배치 — 남는 폭을 항목 사이에 나누되 4 ~ 32로 묶는다. 넘치면 overflow(더보기 메뉴로). */
function toolbarDockedGap(width, itemsWidth, count, { padding = TOOLBAR.dockedPadding } = {}) {
  if (count <= 1) return { gap: 0, overflow: itemsWidth + padding * 2 > width };
  const free = width - padding * 2 - itemsWidth;
  const gap = free / (count - 1);
  return { gap: Math.min(TOOLBAR.dockedMaxGap, Math.max(TOOLBAR.dockedMinGap, gap)), overflow: gap < TOOLBAR.dockedMinGap };
}

// Tooltips 규칙 — M3 Plain · Rich tooltip. 순수 계산만 두고 DOM은 patterns.js가 다룬다.

/** 치수(Compose Tooltip.kt · M3 Specs): plain 높이 24 · 최소 폭 40 · 좌우 8 · 최대 200, rich 최대 320 · 좌우 16, 대상과 4(경계 없는 글이면 8), 꼬리 16×8, 닫힘 1.5초 */
const TOOLTIP = { plainMaxWidth: 200, richMaxWidth: 320, gap: 4, textGap: 8, caret: { width: 16, height: 8 }, hideDelay: 1500, step: 8, margin: 8 };

const ttClamp = (v, lo, hi) => Math.min(Math.max(v, lo), Math.max(lo, hi));
/** 화면 안으로 밀 때는 8 단위로 움직인다(M3 Dynamic positioning) */
const ttSnap = (value, origin) => origin + Math.round((value - origin) / TOOLTIP.step) * TOOLTIP.step;

/**
 * 위치 — anchor · bounds는 같은 좌표의 { left, top, width, height }, size는 { width, height }.
 * plain: 대상 위 가운데(앱 바 안이면 below) — 위에 자리가 없으면 아래로.
 * rich: 대상 오른쪽 아래(대상을 가리지 않음) — 오른쪽이 넘치면 왼쪽 아래, 아래가 넘치면 위로.
 */
function tooltipPlace(kind, anchor, size, bounds, { below = false, gap = TOOLTIP.gap } = {}) {
  const m = TOOLTIP.margin;
  const minL = bounds.left + m, maxL = bounds.left + bounds.width - size.width - m;
  const minT = bounds.top + m, maxT = bounds.top + bounds.height - size.height - m;
  if (kind === 'plain') {
    const above = anchor.top - gap - size.height;
    const under = anchor.top + anchor.height + gap;
    let side = below ? 'bottom' : 'top';
    if (side === 'top' && above < minT) side = 'bottom';
    else if (side === 'bottom' && under > maxT && above >= minT) side = 'top';
    const center = anchor.left + anchor.width / 2 - size.width / 2;
    const left = center < minL || center > maxL ? ttSnap(ttClamp(center, minL, maxL), center) : center;
    return { left: ttClamp(left, minL, maxL), top: side === 'top' ? above : under, side, align: 'center' };
  }
  let align = 'end';
  let left = anchor.left + anchor.width;
  if (left > maxL) { align = 'start'; left = anchor.left - size.width; }
  if (left < minL) { align = 'center'; left = ttClamp(ttSnap(anchor.left + anchor.width / 2 - size.width / 2, anchor.left), minL, maxL); }
  let side = 'bottom';
  let top = anchor.top + anchor.height + gap;
  if (top > maxT) { side = 'top'; top = anchor.top - gap - size.height; }
  return { left, top: Math.max(top, minT), side, align };
}

/** 닫힘 규칙 — transient는 대상 · 툴팁을 떠난 뒤 1.5초, persistent는 다른 요소와 상호작용할 때만(마우스 이탈로는 닫히지 않음). Esc는 둘 다 바로. */
function tooltipHideDelay(kind, reason) {
  if (reason === 'escape') return 0;
  if (kind === 'persistent') return reason === 'outside' ? 0 : Infinity;
  return reason === 'leave' || reason === 'blur' ? TOOLTIP.hideDelay : 0;
}

// FAB menu 규칙 — M3 Expressive FAB menu(Compose FloatingActionButtonMenu · FabMenuBaselineTokens). DOM은 patterns.js.

// 치수는 CSS(.m3-fab-menu)가 맡는다: 닫기 버튼 56(full · 아이콘 20) · 메뉴와 8, 항목 높이 56 · 사이 4 · 앞뒤 24 · 아이콘 24 · 아이콘-글 8, 그림자 3, 항목 2 ~ 6.

/**
 * 항목이 나타나는 순서 지연 — FAB에 가까운 항목(아래)부터 하나씩(Compose stagger, SlowEffects).
 * index는 위에서 0부터, total ms를 항목 수로 나눈다. 닫을 때는 위 항목부터 거꾸로.
 */
function fabMenuStagger(index, count, { opening = true, total = 327 } = {}) {
  if (count <= 1) return 0;
  const step = total / count;
  const order = opening ? count - 1 - index : index;
  return Math.round(order * step);
}

// Snackbar 규칙 — Compose SnackbarHost(SnackbarDuration · 한 번에 하나, 순서대로), M3 Snackbar Accessibility.
// 순수 계산만 둔다.

/** 표시 시간(ms) — 짧게 4000 · 길게 10000(Compose). 동작 버튼이 있으면 사람이 닫을 때까지(WCAG 2.2.1 — 시간 제한 없는 조작). */
function snackbarDuration({ length = 'short', action = false } = {}) {
  if (action || length === 'indefinite') return Infinity;
  return length === 'long' ? 10000 : 4000;
}

/** 대기열 — 새 스낵바는 뒤에 붙고, 지금 것이 닫히면 다음 것을 보인다(한 번에 하나, M3 Guidelines). 같은 글이 이미 기다리면 넣지 않는다. */
function snackbarEnqueue(queue, item) {
  if (queue.some(q => q.text === item.text && q.action === item.action)) return queue;
  return [...queue, item];
}
function snackbarNext(queue) {
  return { current: queue[0] || null, queue: queue.slice(1) };
}

/** 줄 수 — 글이 한 줄 폭을 넘으면 2(높이 68), 동작 글이 길면(폭의 절반 넘음) 아래 줄로. */
function snackbarLayout({ textWidth, available, actionWidth = 0 }) {
  const longAction = actionWidth > 0 && actionWidth > available / 2;
  const room = longAction ? available : available - actionWidth;
  return { lines: textWidth > room ? 2 : 1, longAction };
}

// Sliders 규칙 — M3 Sliders(Expressive), MDC slider tokens.xml · Compose SliderTokens · Slider.kt(손잡이 간격 6 · 안쪽 모서리 2).
// 순수 계산만 두고(단위 테스트 대상) DOM 그리기 · 조작은 patterns.js가 한다.

/** 크기별 치수 — 트랙 높이 · 손잡이 높이 · 트랙 바깥 모서리 · 안쪽 아이콘(M3 Measurements, M 손잡이는 사이트 52). */
const SLIDER_SIZES = {
  xs: { track: 16, handle: 44, radius: 8, icon: 0 },
  s: { track: 24, handle: 44, radius: 8, icon: 0 },
  m: { track: 40, handle: 52, radius: 12, icon: 24 },
  l: { track: 56, handle: 68, radius: 16, icon: 24 },
  xl: { track: 96, handle: 108, radius: 28, icon: 32 },
};
const SLIDER = { handleWidth: 4, pressedHandleWidth: 2, gap: 6, insideRadius: 2, stop: 4, stopSpace: 6, iconPad: 10 };

const clamp = (v, lo, hi) => Math.min(hi, Math.max(lo, v));

/** 값을 단계에 맞춘다(소수 오차 없이). */
function sliderSnap(value, { min = 0, max = 100, step = 1 } = {}) {
  const v = clamp(value, min, max);
  if (!step) return v;
  const n = Math.round((v - min) / step);
  return clamp(Number((min + n * step).toFixed(10)), min, max);
}

/** 값 ↔ 비율 */
const sliderFraction = (value, min = 0, max = 100) => (max === min ? 0 : (value - min) / (max - min));

/** 손잡이 가운데 위치 — 길이 length 위에서 손잡이 반폭만큼 안쪽(Compose 손잡이 범위). */
function sliderPos(fraction, length, handleWidth = SLIDER.handleWidth) {
  return handleWidth / 2 + clamp(fraction, 0, 1) * (length - handleWidth);
}

/** 포인터 위치 → 값(단계 맞춤). */
function sliderValueAt(pos, length, opts = {}, handleWidth = SLIDER.handleWidth) {
  const { min = 0, max = 100 } = opts;
  const f = clamp((pos - handleWidth / 2) / Math.max(1, length - handleWidth), 0, 1);
  return sliderSnap(min + f * (max - min), opts);
}

/**
 * 트랙 조각 — 손잡이마다 양옆 (반폭 + 간격 6)을 비우고, 조각마다 활성 여부와 양 끝 모서리(바깥 = 크기 모서리, 손잡이 쪽 = 2)를 준다.
 * type: 'standard'(시작 → 손잡이 활성) · 'centered'(가운데 → 손잡이 활성) · 'range'(두 손잡이 사이 활성).
 */
function sliderSegments({ length, positions, type = 'standard', radius = 8, handleWidths = [] }) {
  const cuts = positions.map((p, i) => ({ p, half: (handleWidths[i] ?? SLIDER.handleWidth) / 2 + SLIDER.gap }));
  const mid = length / 2;
  const isActive = (a, b) => {
    const c = (a + b) / 2;
    if (type === 'range') return c > positions[0] && c < positions[positions.length - 1];
    if (type === 'centered') return (c > mid && c < positions[0]) || (c < mid && c > positions[0]);
    return c < positions[0];
  };
  // 가운데형은 가운데에서 활성 · 비활성이 바뀐다(간격 없이)
  const points = [0];
  const edges = [radius];
  cuts.sort((x, y) => x.p - y.p).forEach(({ p, half }) => { points.push(p - half, p + half); edges.push(SLIDER.insideRadius, SLIDER.insideRadius); });
  points.push(length); edges.push(radius);
  const segs = [];
  for (let i = 0; i < points.length; i += 2) {
    let from = points[i], to = points[i + 1];
    if (to - from <= 0.5) continue;
    if (type === 'centered' && mid > from && mid < to) {
      segs.push({ from, to: mid, active: isActive(from, mid), r0: edges[i], r1: 0 });
      segs.push({ from: mid, to, active: isActive(mid, to), r0: 0, r1: edges[i + 1] });
      continue;
    }
    segs.push({ from, to, active: isActive(from, to), r0: edges[i], r1: edges[i + 1] });
  }
  return segs;
}

/**
 * 멈춤 점 — stops(단계 수)가 있으면 단계마다, 없으면 비활성 트랙 끝(끝에서 6 띄움)에만. 손잡이 간격 안의 점은 뺀다.
 * 반환: [{ pos, active }]
 */
function sliderStops({ length, positions, type = 'standard', count = 0, handleWidth = SLIDER.handleWidth }) {
  const lo = SLIDER.stopSpace + SLIDER.stop / 2;
  const hi = length - lo;
  let list;
  if (count > 1) list = Array.from({ length: count }, (_, i) => clamp(sliderPos(i / (count - 1), length, handleWidth), lo, hi));
  else if (type === 'standard') list = [hi];
  else list = [lo, hi];
  const keep = p => positions.every(h => Math.abs(p - h) > handleWidth / 2 + SLIDER.gap + SLIDER.stop / 2);
  const segs = sliderSegments({ length, positions, type });
  const activeAt = p => segs.some(s => s.active && p >= s.from && p <= s.to);
  return list.filter(keep).map(pos => ({ pos, active: activeAt(pos) }));
}

/**
 * 키보드 — 오른쪽 · 위 +단계, 왼쪽 · 아래 −단계(RTL 가로는 좌우 반대), Page Up · Down ±10%(최소 한 단계), Home · End 끝.
 * 범위형은 lo · hi로 다른 손잡이를 넘지 못하게 한다.
 */
function sliderKey(value, key, { min = 0, max = 100, step = 1, rtl = false, lo = min, hi = max } = {}) {
  const s = step || (max - min) / 100;
  const page = Math.max(s, Math.round(((max - min) / 10) / s) * s);
  const map = { ArrowUp: s, ArrowDown: -s, ArrowRight: rtl ? -s : s, ArrowLeft: rtl ? s : -s, PageUp: page, PageDown: -page };
  let next = value;
  if (key in map) next = value + map[key];
  else if (key === 'Home') next = min;
  else if (key === 'End') next = max;
  else return null;
  return clamp(sliderSnap(next, { min, max, step }), lo, hi);
}

/** 범위형에서 포인터에 가까운 손잡이 — 같으면 움직일 방향 쪽. */
function sliderNearest(positions, pos) {
  let best = 0;
  positions.forEach((p, i) => { if (Math.abs(p - pos) < Math.abs(positions[best] - pos) || (Math.abs(p - pos) === Math.abs(positions[best] - pos) && pos > p)) best = i; });
  return best;
}

// Sheets 규칙 — M3 Bottom sheets · Side sheets, MDC BottomSheetBehavior · Compose SheetDefaults(임계 56).
// 순수 계산만 두고(단위 테스트 대상) DOM 조작은 patterns.js가 한다.

const SHEET = {
  maxWidth: 640,          // 바텀 시트 최대 폭(M3 · MDC · Compose SheetMaxWidth)
  wideMargin: 56,         // 창이 640보다 넓으면 위 · 양옆 여백 56(M3 Measurements)
  topMargin: 72,          // 좁은 창 위 여백
  peek: 56,               // 표준 시트 접힘 높이(Compose SheetPeekHeight)
  threshold: 56,          // 끌기 판정 거리(Compose PositionalThreshold)
  velocity: 125,          // 휙 밀기 판정 속도 px/s(Compose VelocityThreshold 125dp/s)
  sideWidth: 256,         // 사이드 시트 폭(MDC 토큰), 최대 400(M3)
  sideMaxWidth: 400,
  sideDetachedMargin: 16,
};

/**
 * 상태별 아래로 밀린 거리(px). height = 시트 높이, frame = 보이는 영역 높이.
 * expanded 0 · partial(모달 반만) · collapsed(표준, peek만 보임) · hidden(완전히 내려감).
 */
function sheetOffset(state, height, frame) {
  if (state === 'expanded') return 0;
  if (state === 'partial') return Math.max(0, height - Math.round(frame / 2));
  if (state === 'collapsed') return Math.max(0, height - SHEET.peek);
  return height;
}

/**
 * 끌기를 놓았을 때 다음 상태 — 휙 밀었으면(속도) 그 방향, 아니면 임계(56) 넘게 아래로면 한 단계 내리고, 위로면 한 단계 올린다.
 * 모달: expanded ↔ partial → hidden(닫힘). 표준: expanded ↔ collapsed(숨지 않음).
 */
function sheetSettle(type, state, dy, velocity = 0) {
  const order = type === 'modal' ? ['expanded', 'partial', 'hidden'] : ['expanded', 'collapsed'];
  const i = Math.max(0, order.indexOf(state));
  // 휙 밀기 — 놓는 순간 속도가 125 px/s를 넘으면 거리와 상관없이 그 방향으로 한 단계(Compose VelocityThreshold)
  if (velocity > SHEET.velocity) return order[Math.min(order.length - 1, i + 1)];
  if (velocity < -SHEET.velocity) return order[Math.max(0, i - 1)];
  if (dy > SHEET.threshold) return order[Math.min(order.length - 1, i + 1)];
  if (dy < -SHEET.threshold) return order[Math.max(0, i - 1)];
  return order[i];
}

/** 끌기 손잡이를 누르거나 Enter · Space — 펼침과 접힘(모달은 반만)을 번갈아(MDC 접근성: 손잡이 탭으로 상태 순환). */
function sheetHandleNext(type, state) {
  if (type === 'modal') return state === 'expanded' ? 'partial' : 'expanded';
  return state === 'expanded' ? 'collapsed' : 'expanded';
}

/** 놓기 직전 속도(px/s) — 최근 100ms 안의 포인터 기록(시각 ms, y)으로 잰다. 기록이 모자라면 0. */
function sheetVelocity(samples, window = 100) {
  if (samples.length < 2) return 0;
  const last = samples[samples.length - 1];
  const recent = samples.filter(s => last.t - s.t <= window);
  const first = recent.length >= 2 ? recent[0] : samples[samples.length - 2];
  const dt = last.t - first.t;
  return dt > 0 ? ((last.y - first.y) / dt) * 1000 : 0;
}

// Navigation 규칙 — M3 Navigation bar · Navigation rail(Expressive), Compose ShortNavigationBar · WideNavigationRail.
// 순수 계산만 두고(단위 테스트 대상) DOM 조작은 patterns.js가 한다.

/**
 * 가운데 정렬(가로 항목) 바의 양쪽 여백 — Compose calculateCenteredContentHorizontalPadding.
 * 한쪽 비율 = (100 − 10 × (항목 수 + 3)) / 2 %. 항목이 7개 이상이면 0.
 */
function navCenteredPadding(count, barWidth) {
  if (count > 6) return 0;
  const ratio = ((100 - 10 * (count + 3)) / 2) / 100;
  return Math.max(0, Math.round(ratio * barWidth));
}

const NAV_RAIL = {
  collapsed: 96,
  narrow: 80,
  expandedMin: 220,
  expandedMax: 360,
  itemHorizontalPadding: 20,   // Compose WNRItemHorizontalPadding
};

/**
 * 펼친 레일 폭 — 가장 넓은 항목(또는 머리) + 20, 220 ~ 360으로 자른다(Compose WideNavigationRail 측정).
 */
function navRailExpandedWidth(widestContent) {
  const want = Math.max(0, widestContent) + NAV_RAIL.itemHorizontalPadding;
  return Math.min(NAV_RAIL.expandedMax, Math.max(NAV_RAIL.expandedMin, want));
}

/**
 * 레일 안 화살표 이동(M3 Navigation rail Accessibility: Tab · 화살표). 세로 목록이라 위 · 아래, 끝에서 멈춘다.
 * 바는 Tab만 쓴다(M3 Navigation bar Accessibility) — 다른 키는 그대로 둔다.
 */
function navNextIndex(index, count, key) {
  if (count <= 0) return -1;
  if (key === 'ArrowDown') return Math.min(count - 1, index + 1);
  if (key === 'ArrowUp') return Math.max(0, index - 1);
  if (key === 'Home') return 0;
  if (key === 'End') return count - 1;
  return index;
}

/**
 * 목적지를 고른 결과 — 이미 고른 항목을 다시 누르면 'reselect'(그 화면 맨 위로 스크롤, M3 Guidelines),
 * 다른 항목이면 'navigate'. 바깥 범위는 'none'.
 */
function navSelect(current, index, count) {
  if (index < 0 || index >= count) return { active: current, action: 'none' };
  if (index === current) return { active: current, action: 'reselect' };
  return { active: index, action: 'navigate' };
}

// Badge 값 규칙 — M3: 최대 4자("+" 포함), 숫자는 999를 넘으면 "999+" (MDC maxNumber 999 · maxCharacterCount 4)
const BADGE_MAX_NUMBER = 999;

// true = small(점) 배지, 0 이하·false = 배지 없음, 숫자 = large 배지 글자
function formatBadgeCount(value, max = BADGE_MAX_NUMBER) {
  if (value === true) return '';
  const n = Math.floor(Number(value));
  if (!Number.isFinite(n) || n <= 0) return null;
  return n > max ? `${max}+` : String(n);
}

// 배지는 목적지 이름 뒤에 읽힌다. 숫자 배지는 개수, 점 배지는 "새 알림".
function badgeAccessibleLabel(label, value, max = BADGE_MAX_NUMBER) {
  if (value === true) return `${label}, 새 알림`;
  const text = formatBadgeCount(value, max);
  if (text === null) return label;
  return Number(value) > max ? `${label}, 새 알림 ${max}개 이상` : `${label}, 새 알림 ${text}개`;
}

// Large 배지 최대 폭(M3 16×34). 시스템 글꼴이 넓어 넘치면 자간만 줄여 맞춘다.
const BADGE_MAX_WIDTH = 34;
const BADGE_MIN_TRACKING = -1.5;

// width: 현재 폭(px), tracking: 현재 자간(px), chars: 글자 수 → 새 자간(px) 또는 null(조정 불필요)
function badgeTracking(width, tracking, chars, max = BADGE_MAX_WIDTH, min = BADGE_MIN_TRACKING) {
  if (!(width > max) || !chars) return null;
  const need = Math.floor((tracking - (width - max) / chars) * 20) / 20;
  return Math.max(min, need);
}

/**
 * iconCatalog.js
 * Styles › Icons 카탈로그(Google Fonts Material Symbols)의 검색 · 카테고리 거르기.
 * 데이터는 scripts/material-symbols.js(인기순 [name, categoryIndex, path])이고 여기는 순수 계산만 한다.
 */

/** 검색어를 아이콘 이름 형식으로 — 소문자, 공백 · 하이픈은 밑줄(Google Fonts 이름 규칙). */
function normalizeIconQuery(query) {
  return String(query || '').trim().toLowerCase().replace(/[\s-]+/g, '_');
}

/**
 * 조건에 맞는 아이콘을 원래 순서(인기순) 그대로 돌려준다.
 * 이름이 검색어로 시작하는 것을 앞에, 이름 중간에 들어 있는 것을 뒤에 둔다(각 묶음 안은 인기순).
 * @param {Array<[string, number, string]>} icons
 * @param {{query?: string, category?: number|'all'}} filter
 */
function filterIcons(icons, { query = '', category = 'all' } = {}) {
  const q = normalizeIconQuery(query);
  const inCategory = category === 'all' ? icons : icons.filter(icon => icon[1] === category);
  if (!q) return inCategory;
  const starts = [];
  const contains = [];
  for (const icon of inCategory) {
    if (icon[0].startsWith(q)) starts.push(icon);
    else if (icon[0].includes(q)) contains.push(icon);
  }
  return starts.concat(contains);
}

/** 카테고리별 아이콘 수(칩 이름 옆 숫자). 인덱스 = categories 배열 순서. */
function countByCategory(icons, categoryCount) {
  const counts = new Array(categoryCount).fill(0);
  for (const icon of icons) counts[icon[1]] += 1;
  return counts;
}

/**
 * Google Fonts 아이콘 필터와 같은 축(M3 Applying icons › Customizing Symbols).
 * 기본값은 카탈로그 데이터(material-symbols.js)에 실린 변형이다 — 다른 조합만 공식 저장소에서 받아 온다.
 */
const ICON_AXES = {
  style: ['outlined', 'rounded', 'sharp'],
  fill: [0, 1],
  weight: [100, 200, 300, 400, 500, 600, 700],
  grade: [-25, 0, 200],
  size: [20, 24, 40, 48],
};
const ICON_DEFAULTS = { style: 'outlined', fill: 0, weight: 400, grade: 0, size: 24 };

/** 카탈로그에 실린 기본 변형인지(받아 올 필요 없음). */
function isDefaultVariant(axes) {
  return Object.keys(ICON_DEFAULTS).every(key => axes[key] === ICON_DEFAULTS[key]);
}

/**
 * google/material-design-icons의 변형 SVG 주소.
 * 파일 이름: {name}_{[wght{W}][grad{N25|200}][fill1]}_{size}px.svg — 기본값(wght 400 · grad 0 · fill 0)은 빼고 적는다.
 */
function iconVariantUrl(name, { style = 'outlined', fill = 0, weight = 400, grade = 0, size = 24 } = {}) {
  let axis = '';
  if (weight !== 400) axis += `wght${weight}`;
  if (grade !== 0) axis += `grad${grade < 0 ? `N${-grade}` : grade}`;
  if (fill === 1) axis += 'fill1';
  const file = `${name}${axis ? `_${axis}` : ''}_${size}px.svg`;
  return `https://raw.githubusercontent.com/google/material-design-icons/master/symbols/web/${name}/materialsymbols${style}/${file}`;
}

// Local calendar dates avoid UTC/daylight-saving shifts in the displayed day.
function calendarDate(year, month, day) {
  return new Date(year, month, day, 12);
}

function shiftCalendarMonth(date, offset) {
  const first = calendarDate(date.getFullYear(), date.getMonth() + offset, 1);
  const last = calendarDate(first.getFullYear(), first.getMonth() + 1, 0).getDate();
  return calendarDate(first.getFullYear(), first.getMonth(), Math.min(date.getDate(), last));
}

function calendarKey(date) {
  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`;
}

function calendarWeeks(date) {
  const year = date.getFullYear(), month = date.getMonth();
  const firstDay = calendarDate(year, month, 1).getDay();
  const lastDay = calendarDate(year, month + 1, 0).getDate();
  return Array.from({ length: Math.ceil((firstDay + lastDay) / 7) }, (_, week) =>
    Array.from({ length: 7 }, (_, weekday) => {
      const day = week * 7 + weekday - firstDay + 1;
      return day > 0 && day <= lastDay ? calendarDate(year, month, day) : null;
    }));
}

/**
 * bwCube.js
 * Overview의 "여덟 색 사이의 색" 그림 — RGB 정육면체에서 한 색이 여덟 꼭짓점(실측 색)에 얼마나 가까운지 계산한다.
 * 가중치는 bwIndex.js의 3선형 보간과 같은 식이다: Σ(가중치 × 꼭짓점 값) = calcBwIndex.
 */

// 꼭짓점 순서는 Overview의 여덟 색 막대(값이 낮은 순)와 같다. on = [R, G, B] 소자가 켜졌는지.
const CUBE_VERTEX_DEFS = [
  ['black', '검정', [0, 0, 0]],
  ['red', '빨강', [1, 0, 0]],
  ['green', '초록', [0, 1, 0]],
  ['yellow', '노랑', [1, 1, 0]],
  ['blue', '파랑', [0, 0, 1]],
  ['magenta', '자홍', [1, 0, 1]],
  ['cyan', '청록', [0, 1, 1]],
  ['white', '흰색', [1, 1, 1]],
];

const CUBE_VERTICES = CUBE_VERTEX_DEFS.map(([key, name, on]) => ({
  key, name, on,
  value: calcBwIndex(on[0] * 255, on[1] * 255, on[2] * 255),
}));

/**
 * 색 하나가 여덟 꼭짓점에 가까운 정도(합 1). CUBE_VERTICES와 같은 순서.
 * @param {number} r 0~255
 * @param {number} g 0~255
 * @param {number} b 0~255
 * @returns {number[]}
 */
function cubeWeights(r, g, b) {
  const n = [r, g, b].map(v => Math.min(255, Math.max(0, v)) / 255);
  return CUBE_VERTICES.map(({ on }) => on.reduce((w, lit, axis) => w * (lit ? n[axis] : 1 - n[axis]), 1));
}

/**
 * 정육면체 안의 점을 그림 좌표로 옮긴다(가로 R, 세로 G, 안쪽 B).
 * @param {number} r 0~1
 * @param {number} g 0~1
 * @param {number} b 0~1
 * @param {{ size: number, x: number, y: number }} box 앞면 한 변의 길이와 검정 꼭짓점의 위치
 * @returns {[number, number]}
 */
function cubePoint(r, g, b, box) {
  return [box.x + (r + b * 0.45) * box.size, box.y - (g + b * 0.42) * box.size];
}

// Dialogs 로직 — M3 Dialogs Accessibility · Guidelines.

/** 대화상자 안의 포커스 대상(보이는 것, 비활성 제외) — DOM 순서. */
const DIALOG_FOCUSABLE = 'button:not(:disabled), input:not(:disabled), select:not(:disabled), textarea:not(:disabled), a[href], [tabindex]:not([tabindex="-1"])';

/**
 * Tab 순환 — 마지막에서 Tab이면 처음으로, 처음에서 Shift+Tab이면 마지막으로(M3 Keyboard navigation).
 * 순환이 필요 없으면 -1(브라우저 기본 이동).
 */
function dialogTabTarget(index, count, shift) {
  if (count <= 0) return -1;
  if (shift && index <= 0) return count - 1;
  if (!shift && index >= count - 1) return 0;
  return -1;
}

/** 전체 화면 대화상자의 저장하지 않은 변경 여부 — 처음 값과 지금 값을 필드별로 비교한다. */
function dialogHasChanges(initial, current) {
  const keys = new Set([...Object.keys(initial || {}), ...Object.keys(current || {})]);
  for (const key of keys) if (String(initial?.[key] ?? '').trim() !== String(current?.[key] ?? '').trim()) return true;
  return false;
}

// Date pickers 로직 — M3 Date pickers Accessibility(키보드 · 입력 형식)와 Guidelines(범위 선택)를 따른다.
// 달력 계산 기본(윤년 · 달 이동)은 calendar.js를 쓴다.

/** 두 날짜가 같은 날인지. */
function sameDay(a, b) {
  return !!a && !!b && a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth() && a.getDate() === b.getDate();
}

/** 날 단위 비교값(시각 무시). */
function dayValue(date) { return date.getFullYear() * 10000 + date.getMonth() * 100 + date.getDate(); }

/**
 * 키보드로 옮겨 갈 날짜(M3 Accessibility — Keyboard navigation).
 * 화살표 ±1일 · ±7일, Home/End 그 달 첫날 · 마지막 날, PageUp/PageDown 전후 달 같은 날,
 * Shift+PageUp/PageDown 전후 해 같은 날. 해당 키가 아니면 null. RTL이면 좌우 반전.
 */
function datePickerKeyTarget(date, key, { shift = false, rtl = false } = {}) {
  const y = date.getFullYear(); const m = date.getMonth(); const d = date.getDate();
  const left = rtl ? 1 : -1;
  switch (key) {
    case 'ArrowLeft': return calendarDate(y, m, d + left);
    case 'ArrowRight': return calendarDate(y, m, d - left);
    case 'ArrowUp': return calendarDate(y, m, d - 7);
    case 'ArrowDown': return calendarDate(y, m, d + 7);
    case 'Home': return calendarDate(y, m, 1);
    case 'End': return calendarDate(y, m + 1, 0);
    case 'PageUp': return shiftCalendarMonth(date, shift ? -12 : -1);
    case 'PageDown': return shiftCalendarMonth(date, shift ? 12 : 1);
    default: return null;
  }
}

/**
 * 직접 입력한 날짜 해석(연·월·일 순서). M3: 입력 중에는 형식을 바꾸지 않고, 대시 · 공백 · 슬래시 · 점과
 * 한 자리 월·일(앞 0 생략)을 모두 받는다. 8자리 숫자(20260917)도 받는다. 없는 날짜면 null.
 */
function parseDateInput(text) {
  const raw = String(text ?? '').trim();
  let parts;
  if (/^\d{8}$/.test(raw)) parts = [raw.slice(0, 4), raw.slice(4, 6), raw.slice(6, 8)];
  else parts = raw.split(/[\s./-]+/).filter(Boolean);
  if (parts.length !== 3 || !parts.every(p => /^\d+$/.test(p)) || parts[0].length !== 4) return null;
  const [y, m, d] = parts.map(Number);
  if (m < 1 || m > 12 || d < 1) return null;
  const date = calendarDate(y, m - 1, d);
  return date.getMonth() === m - 1 && date.getDate() === d ? date : null;
}

/** 입력 칸에 다시 써 줄 형식(입력을 마친 뒤에만 적용). YYYY/MM/DD */
function formatDateInput(date) {
  const pad = n => String(n).padStart(2, '0');
  return `${date.getFullYear()}/${pad(date.getMonth() + 1)}/${pad(date.getDate())}`;
}

/**
 * 범위 선택 — 시작일이 없거나 이미 끝났으면 새 시작, 시작일보다 앞을 누르면 시작일을 옮기고,
 * 같거나 뒤를 누르면 끝일로 확정한다.
 */
function nextRangeSelection({ start = null, end = null } = {}, clicked) {
  if (!start || end || dayValue(clicked) < dayValue(start)) return { start: clicked, end: null };
  return { start, end: clicked };
}

/** 범위 안(시작·끝 포함)인지. */
function inDateRange(date, start, end) {
  if (!start || !end) return false;
  const v = dayValue(date);
  return v >= dayValue(start) && v <= dayValue(end);
}

/** 선택 가능한 범위 안인지(min · max 포함, 없으면 제한 없음). */
function dateSelectable(date, min = null, max = null) {
  const v = dayValue(date);
  return (!min || v >= dayValue(min)) && (!max || v <= dayValue(max));
}

/** 연도 목록(오름차순). */
function yearRange(from, to) {
  return Array.from({ length: Math.max(0, to - from + 1) }, (_, i) => from + i);
}

// Time pickers 로직 — 다이얼 각도 ↔ 값, 12/24시간 변환, 입력 칸 해석.
// 치수는 M3 Time pickers Specs · Compose TimePicker.kt: 다이얼 256, 바깥 고리 반지름 101, 안쪽 고리 69.

const TIME_DIAL = { size: 256, outer: 101, inner: 69, handle: 48 };

/** 값이 가리키는 각도(12시 방향 0°, 시계 방향). mode: 'hour' | 'minute' */
function dialAngle(value, mode) {
  return mode === 'minute' ? (value % 60) * 6 : (value % 12) * 30;
}

/**
 * 다이얼 위 점(중심 기준 x 오른쪽 +, y 아래 +)을 값으로. 시는 가장 가까운 시, 분은 가장 가까운 분.
 * 24시간 시 선택은 중심에서 두 고리 사이보다 가까우면 안쪽 고리(12–23), 아니면 바깥 고리(0–11).
 * 반환: 시 12시간제면 1–12, 24시간제면 0–23. 분 0–59.
 */
function dialValueAt(x, y, mode, { is24h = false, dial = TIME_DIAL } = {}) {
  let deg = Math.atan2(x, -y) * 180 / Math.PI;
  if (deg < 0) deg += 360;
  if (mode === 'minute') return Math.round(deg / 6) % 60;
  const h = Math.round(deg / 30) % 12;
  if (!is24h) return h === 0 ? 12 : h;
  const inner = Math.hypot(x, y) < (dial.outer + dial.inner) / 2;
  return inner ? h + 12 : h;
}

/** 다이얼 숫자 위치(중심 기준). 24시간 안쪽 고리는 12–23. */
function dialLabelPosition(value, mode, { is24h = false, dial = TIME_DIAL } = {}) {
  const angle = dialAngle(value, mode) * Math.PI / 180;
  const r = mode === 'hour' && is24h && value >= 12 ? dial.inner : dial.outer;
  const round = v => (Math.round(v * 100) / 100) + 0;
  return { x: round(Math.sin(angle) * r), y: round(-Math.cos(angle) * r), r };
}

/** 12시간 표시 → 24시간. hour12 1–12, period 'AM' | 'PM' */
function to24Hour(hour12, period) {
  const h = hour12 % 12;
  return period === 'PM' ? h + 12 : h;
}

/** 24시간 → { hour12, period } */
function from24Hour(hour24) {
  const h = ((hour24 % 24) + 24) % 24;
  return { hour12: h % 12 === 0 ? 12 : h % 12, period: h >= 12 ? 'PM' : 'AM' };
}

/** 입력 칸 해석. 시(12시간 1–12, 24시간 0–23) · 분(0–59). 숫자 1–2자리가 아니거나 범위 밖이면 null. */
function parseTimeField(text, mode, { is24h = false } = {}) {
  const raw = String(text ?? '').trim();
  if (!/^\d{1,2}$/.test(raw)) return null;
  const n = Number(raw);
  if (mode === 'minute') return n <= 59 ? n : null;
  if (is24h) return n <= 23 ? n : null;
  return n >= 1 && n <= 12 ? n : null;
}

/** 두 자리 표시. */
function pad2(n) { return String(n).padStart(2, '0'); }



































// Saving UI가 장면으로 쓰는 Live 견본의 처음 모습 — 각 블록이 그리거나 상태를 바꾸기 전에 떠 둔다(맨 끝 Saving UI 블록)
const SAVING_SOURCES = {};
Object.values(SAVING_RECIPES).forEach(r => Object.values(r.modes).forEach(m => m.set.flat().forEach(p => {
  if (p.kind === 'live' && !(p.src in SAVING_SOURCES)) SAVING_SOURCES[p.src] = document.querySelector(p.src)?.outerHTML || '';
})));

// 보기 전환 바(아일랜드) 공통 — 고른 값 기억(localStorage) · 라디오 표시. 저장소가 없으면 기본값으로 동작한다.
const loadView = (key, view) => { try { Object.assign(view, JSON.parse(localStorage.getItem(key)) || {}); } catch (error) { /* 저장소 없음 */ } return view; };
const saveView = (key, view) => { try { localStorage.setItem(key, JSON.stringify(view)); } catch (error) { /* 저장소 없음 */ } };
const markRadios = (group, value) => group?.querySelectorAll('[role="radio"]').forEach(button => {
  const on = button.dataset.value === value;
  button.setAttribute('aria-checked', String(on));
  button.tabIndex = on ? 0 : -1;
});
// 아일랜드에서 값을 고르면(클릭 · 방향키) 그 축의 값을 넘긴다.
const onIslandPick = (bar, axisSelector, pick) => {
  const sync = event => {
    const group = event.target.closest(axisSelector);
    const checked = group?.querySelector('[role="radio"][aria-checked="true"]');
    if (checked) pick(checked.dataset.value, group);
  };
  bar?.addEventListener('click', sync);
  bar?.addEventListener('keydown', sync);
};


// 탭 전환 (Overview, Styles, Components, Layout, Pages — 왼쪽 내비게이션 레일)
// 세로 탭 목록이라 위 · 아래(좌 · 우도 허용) · Home · End로 이동하고, 옮기면 바로 그 구성을 연다(자동 활성).
// 사이드바에는 그 구성의 하위 메뉴만 보이고, 하위 메뉴가 없으면(Overview) 사이드바 열을 접는다.
const railTabs = [...document.querySelectorAll('.pl-tab')];
function syncSidebar(panelId) {
  const sidebar = document.getElementById('pl-sidebar');
  if (!sidebar) return;
  let hasMenu = false;
  sidebar.querySelectorAll('.pl-side-menu .pl-comp-nav').forEach(nav => {
    const on = nav.dataset.panel === panelId;
    nav.hidden = !on;
    hasMenu ||= on;
  });
  sidebar.toggleAttribute('data-no-menu', !hasMenu);
}
function selectRailTab(tab, { focus = false } = {}) {
  const panelId = 'panel-' + tab.dataset.panel;
  railTabs.forEach(t => {
    const on = t === tab;
    t.classList.toggle('active', on);
    t.setAttribute('aria-selected', String(on));
    t.tabIndex = on ? 0 : -1;
  });
  document.querySelectorAll('.pl-panel').forEach(p => p.classList.toggle('active', p.id === panelId));
  syncSidebar(panelId);
  document.getElementById('library-preview')?.scrollTo({ top: 0 });
  if (focus) tab.focus();
  try { localStorage.setItem('bw-rail-tab', tab.dataset.panel); } catch (error) { /* 저장소 없음 */ }
}
// Overview(라이브러리 소개, 2026-10-18)의 구성 카드 · 버튼 — 해당 레일 탭을 연다. 포커스는 그 탭으로 옮겨 어디로 왔는지 알린다.
document.addEventListener('click', event => {
  const go = event.target.closest('[data-goto-panel]');
  if (!go) return;
  const tab = railTabs.find(t => t.dataset.panel === go.dataset.gotoPanel);
  if (tab) selectRailTab(tab, { focus: true });
});
railTabs.forEach((tab, index) => {
  tab.addEventListener('click', () => selectRailTab(tab));
  tab.addEventListener('keydown', event => {
    let next;
    if (['ArrowDown', 'ArrowRight'].includes(event.key)) next = (index + 1) % railTabs.length;
    if (['ArrowUp', 'ArrowLeft'].includes(event.key)) next = (index + railTabs.length - 1) % railTabs.length;
    if (event.key === 'Home') next = 0;
    if (event.key === 'End') next = railTabs.length - 1;
    if (next === undefined) return;
    event.preventDefault();
    selectRailTab(railTabs[next], { focus: true });
  });
});

// M3 토글 버튼: 누를 때마다 선택 상태를 바꾼다(형태 모핑은 CSS가 맡는다).
document.querySelectorAll('[data-toggle-button]').forEach(button => {
  button.addEventListener('click', () => button.setAttribute('aria-pressed', String(button.getAttribute('aria-pressed') !== 'true')));
});

// ─── Single-selection groups: roving focus and native button activation ───
document.querySelectorAll('.btn-group-connected[role="radiogroup"]').forEach(group => {
  const buttons = [...group.querySelectorAll('.btn')];
  const select = button => buttons.forEach(item => {
    const selected = item === button;
    item.setAttribute('aria-checked', String(selected));
    item.removeAttribute('aria-pressed');
    item.tabIndex = selected ? 0 : -1;
  });
  select(buttons.find(button => button.getAttribute('aria-checked') === 'true') || buttons[0]);
  buttons.forEach((button, index) => {
    button.addEventListener('click', () => select(button));
    button.addEventListener('keydown', event => {
      let next;
      if (['ArrowRight', 'ArrowDown'].includes(event.key)) next = (index + 1) % buttons.length;
      if (['ArrowLeft', 'ArrowUp'].includes(event.key)) next = (index + buttons.length - 1) % buttons.length;
      if (event.key === 'Home') next = 0;
      if (event.key === 'End') next = buttons.length - 1;
      if (next === undefined) return;
      event.preventDefault();
      select(buttons[next]);
      buttons[next].focus();
    });
  });
});

// Split button 메뉴는 Menus 컴포넌트(.m3-menu, 명세 4.6.3)가 연다 — 아래 Menus 블록.
document.querySelector('[data-split-main]')?.addEventListener('click', () => {
  document.getElementById('split-result').textContent = '저장했습니다.';
});

// ─── Motion 곡선 재생기(2026-09-29) — 칸에 마우스를 올리는 동안 점이 실제 지속 시간으로 곡선을 따라간다 ───
// 평소에는 곡선만 보이고, 올리면 처음부터 재생 → 끝에서 머문 뒤 반복, 내리면 멈추고 점을 감춘다.
// 동작 줄이기 설정이면 올렸을 때 점을 끝에만 보인다.
const curvePlayer = (() => {
  const items = new Map();   // svg → { pts, duration, dot, cursor, start }
  const playing = new Set();
  const HOLD = 700;          // 끝에서 머무는 시간(ms)
  let frame = 0;
  const reduce = () => window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
  const yAt = (pts, x) => {
    if (x <= pts[0][0]) return pts[0][1];
    for (let i = 1; i < pts.length; i += 1) {
      const [x1, y1] = pts[i];
      if (x <= x1) { const [x0, y0] = pts[i - 1]; return y0 + (y1 - y0) * ((x - x0) / ((x1 - x0) || 1)); }
    }
    return pts[pts.length - 1][1];
  };
  const place = (item, progress) => {
    const x = progress * 96;
    item.dot.setAttribute('cx', x.toFixed(1));
    item.dot.setAttribute('cy', yAt(item.pts, x).toFixed(1));
    item.cursor.setAttribute('x1', x.toFixed(1));
    item.cursor.setAttribute('x2', x.toFixed(1));
  };
  const tick = now => {
    frame = 0;
    playing.forEach(svg => {
      const item = items.get(svg);
      if (item.start == null) item.start = now;
      const t = (now - item.start) % (item.duration + HOLD);
      place(item, Math.min(1, t / item.duration));
    });
    if (playing.size) frame = requestAnimationFrame(tick);
  };
  const start = svg => {
    const item = items.get(svg);
    svg.toggleAttribute('data-playing', true);
    if (reduce()) { place(item, 1); return; }
    item.start = null;
    place(item, 0);
    playing.add(svg);
    if (!frame) frame = requestAnimationFrame(tick);
  };
  const stop = svg => { playing.delete(svg); svg.removeAttribute('data-playing'); };
  return {
    add(svg, pts, duration) {
      items.set(svg, { pts, duration: Math.max(1, duration), dot: svg.querySelector('.m3-motion-dot'), cursor: svg.querySelector('.m3-motion-cursor'), start: null });
      // 칸(.m3-motion-tile)이 만들어진 뒤에 붙도록 한 박자 늦춘다.
      queueMicrotask(() => {
        const host = svg.closest('.m3-motion-tile') || svg;
        host.addEventListener('pointerenter', () => start(svg));
        host.addEventListener('pointerleave', () => stop(svg));
      });
    },
  };
})();

